        const serverErrors = [];
        const pending = new Set();
        const localRequestFailures = [];
        page.on('request', request => pending.add(request));
        page.on('requestfinished', request => pending.delete(request));
        page.on('requestfailed', request => {
          pending.delete(request);
          if (request.url().startsWith(base)) localRequestFailures.push({path:new URL(request.url()).pathname,error:request.failure()?.errorText || 'unknown'});
        });
        page.on('response', response => { if (response.url().startsWith(base) && response.status() >= 500) serverErrors.push(response.url()); });
