        await featureLink.click();
        await page.locator('.post-page-title').getByText('합성 특집 두 번째 기사').waitFor({timeout:15000});
        await page.goto(new URL('wosm-members',base).toString(),{waitUntil:'domcontentloaded'});
        await page.locator('#wosm-members-body').getByText('프랑스', {exact:false}).first().waitFor({state:'attached',timeout:15000});
        await page.locator('#wosm-members-search').fill('France');
        await page.waitForFunction(() => document.querySelector('#wosm-members-body')?.textContent?.includes('프랑스') && !document.querySelector('#wosm-members-body')?.textContent?.includes('인도'));
        assert.equal(await page.evaluate(() => document.documentElement.scrollWidth <= innerWidth),true,`members overflow at ${width}px`);
        await page.goto(new URL('topics/cub-scouts',base).toString(),{waitUntil:'domcontentloaded'});
